#!/usr/bin/env bash
# Print a rung's briefing, or any slice of the record (FACTS.md, INDEX.md, POSITIONS.md, the ledger, the maps, a note by heading); --help for the usage.
exec python3 "$(dirname "$(readlink -f "$0")")/facts-extract.py" "$@"

[-four-]{+three+}
[-`Number` or-]
[-`asif`-]{+the type assumption+}
[-818)-]{+818, the forms that F-325 lists as refused)+}
{+The count on today's code, with F-325's forms compiled, is not measured.+}
[-26's,-]{+27's,+}
{+At that gate its check of `value object Char` did not finish, so the 0 holds no completed check of that declaration's body (F-54; row 929, the checker's crash).+}
[-`Int`, `Long` and `BigNum`.-]{+by those names (F-328).+}
